        const DATA_SOURCES = [{"name": "For data-driven briefs (mainly AI/ML, Data Analysis, Data Science). Most other tracks need no external dataset.", "description": "", "url": ""}, {"name": "THREE WAYS A FELLOW CAN GET DATA", "description": "", "url": ""}, {"name": "1. Use an open dataset", "description": "Download from a public Nigerian or global open-data portal (list below). Best when reliable public data exists (prices, health, power, elections).", "url": ""}, {"name": "2. Collect your own data", "description": "Gather real data locally — a short survey (Google Forms), a local business's records (with permission), or your own observations. Best for POS, SME, vendor and community briefs. Adds strong authenticity.", "url": ""}, {"name": "3. Generate documented synthetic data", "description": "Where no real data is practical and the brief is about the technique (a pipeline, a dashboard, a fraud demo), create realistic mock data and clearly document how. Acceptable when stated; real data is preferred for insight briefs.", "url": ""}, {"name": "KEY OPEN-DATA SOURCES (NIGERIA & GLOBAL)", "description": "", "url": ""}, {"name": "Source", "description": "What you'll find", "url": ""}, {"name": "National Bureau of Statistics (NBS)", "description": "Inflation/CPI, food & fuel prices, unemployment, GDP, agriculture, demographics", "url": "nigerianstat.gov.ng"}, {"name": "Central Bank of Nigeria (CBN)", "description": "Exchange & interest rates, financial statistics", "url": "cbn.gov.ng"}, {"name": "Nigeria Open Data Portal", "description": "Assorted government datasets", "url": "data.gov.ng"}, {"name": "Humanitarian Data Exchange (HDX)", "description": "Health, flood, food security, population, agriculture (Nigeria)", "url": "data.humdata.org"}, {"name": "WFP Food Prices", "description": "Market prices by state/commodity (tomato, onion, rice)", "url": "via HDX or Kaggle"}, {"name": "NCDC", "description": "Disease/outbreak data (e.g., malaria)", "url": "ncdc.gov.ng"}, {"name": "NERC", "description": "Electricity supply & DisCo reports", "url": "nerc.gov.ng"}, {"name": "INEC", "description": "Election results", "url": "inecnigeria.org"}, {"name": "NCC", "description": "Telecom subscriber statistics", "url": "ncc.gov.ng"}, {"name": "NiMet / NIHSA", "description": "Rainfall and flood data", "url": "nimet.gov.ng / nihsa.gov.ng"}, {"name": "BudgIT / Open Treasury", "description": "Public budget & spending data", "url": "yourbudgit.com / opentreasury.gov.ng"}, {"name": "Kaggle", "description": "Search 'Nigeria'; also PaySim, Telco Churn, Student Performance", "url": "kaggle.com/datasets"}, {"name": "World Bank Open Data", "description": "Nigeria development indicators", "url": "data.worldbank.org"}, {"name": "Google Dataset Search", "description": "Search across many dataset providers", "url": "datasetsearch.research.google.com"}];

        // State Management
        let currentTrack = 'ALL';
